export type AiUiBlockPayloadMemoryView = typeof AiUiBlockPayloadMemoryView[keyof typeof AiUiBlockPayloadMemoryView];


export const AiUiBlockPayloadMemoryView = {
  MY_INTERESTS: 'MY_INTERESTS',
  MEMORY_SUMMARY: 'MEMORY_SUMMARY',
  MEMORY_CONFIRMATION: 'MEMORY_CONFIRMATION',
  MEMORY_UPDATED: 'MEMORY_UPDATED',
} as const;

export type AiUiBlockPayloadDraft = { [key: string]: unknown };

/**
 * Typed seller draft review built by the server: each value with its provenance (USER_DECLARED, IMAGE_INFERRED, DINAR_DERIVED, SERVER_FACT, UNKNOWN), image guesses marked as needing confirmation, every missing required field, and the allowed actions (PUBLISH only when nothing is missing, EDIT, CANCEL).
 */
export type AiUiBlockPayloadDraftReview = { [key: string]: unknown };

/**
 * Current server facts of the compared listings side by side; values the seller did not state are null ("غير معروف").
 */
export type AiUiBlockPayloadComparison = { [key: string]: unknown };

/**
 * Review of a pending, confirm-only selection (adds to cart after re-reading price, stock and account); never pays.
 */
export type AiUiBlockPayloadPurchaseReview = { [key: string]: unknown };

/**
 * The versioned card envelope the server decides for this block (schemaVersion 1): surface type and identity, resource, conversation, market context, lifecycle, allowed actions, pending review, expiry, refresh strategy, source timestamp and accessibility label. The client validates it before rendering and never invents an action the server did not allow.
 */
export type AiUiBlockPayloadCard = { [key: string]: unknown };

/**
 * Seller insight from DINAR-internal facts only: price comparables (count, range, median), listing factors phrased as possibilities (never as causes), or a BUSINESS_SUMMARY of the seller's own stock, order counts or per-listing results (shape: SellerBusinessInsight in @workspace/api-zod/conversation-runtime).
 */
export type AiUiBlockPayloadSellerInsight = { [key: string]: unknown };

export type AiUiBlockPayloadAttributes = { [key: string]: unknown };

/**
 * Generative UI. The server-resolved layout of a listing block, proposed by the model and validated against this block's own verified result set; a highlight is a labelled suggestion and never a sponsored listing.
 */
export type AiUiBlockPayloadComposition = {
  source: AiUiBlockPayloadCompositionSource;
  layout: AiUiBlockPayloadCompositionLayout;
  /**
     * @minLength 1
     * @maxLength 200
     */
  highlightId?: string;
};

export type AiUiBlockPayloadManagementPreview = {
  previewId: string;
  action: AiUiBlockPayloadManagementPreviewAction;
  listingId: string;
  listingTitle: string;
  fieldLabel: string;
  beforeValue: string;
  afterValue: string;
  status: AiUiBlockPayloadManagementPreviewStatus;
};

/**
 * Allowlisted employment view (jobs, CV profile, candidates, applications, pending action), validated server-side.
 */
export type AiUiBlockPayloadEmployment = { [key: string]: unknown };

/**
 * Allowlisted delivery/location view for the order's own participant, rebuilt server-side on every read. Stored copies never contain coordinates or address text.
 */
export type AiUiBlockPayloadDelivery = { [key: string]: unknown };

/**
 * Allowlisted seller promotion view (plans, review, campaigns), rebuilt from server state on every read. Prices come only from admin plans.
 */
export type AiUiBlockPayloadPromotion = { [key: string]: unknown };

/**
 * Allowlisted driver view (profile, review, coarse work cards, assignments), rebuilt from server state on every read. Never contains contacts or coordinates.
 */
export type AiUiBlockPayloadDriver = { [key: string]: unknown };

/**
 * Phase 2 model-driven display. A server-composed card (ComposedSurface) of the actor's own verified figures in the form the model chose; built from server records only and validated again by the client before rendering.
 */
export type AiUiBlockPayloadDisplaySurface = { [key: string]: unknown };

/**
 * Allowlisted provider connection view (review, status, safe key prefix). Never contains a key, secret or credential hash.
 */
export type AiUiBlockPayloadProvider = { [key: string]: unknown };

/**
 * Allowlisted D3-A business view (setup, profile, catalog, orders, insights), refreshed from the owner's live D2 identity and D3 operating rows on every read.
 */
export type AiUiBlockPayloadBusiness = { [key: string]: unknown };

/**
 * Policy review card (W02-ULTRA B10): the current version, effective date, legal-review status and reading path of each policy that requires acceptance, whether this user accepted it, and the review id whose exact versions an acceptance records. Contract acceptance only; optional privacy consents are unaffected.
 */
export type AiUiBlockPayloadPolicyReview = { [key: string]: unknown };

export type AiUiBlockPayloadMemoryGroupsItemItemsItem = {
  /** @maxLength 80 */
  topic: string;
  /** @maxLength 120 */
  label: string;
  /** @maxLength 160 */
  reason: string;
};

export type AiUiBlockPayloadMemoryGroupsItem = {
  /** @maxLength 80 */
  label: string;
  /** @maxItems 12 */
  items: AiUiBlockPayloadMemoryGroupsItemItemsItem[];
};

/**
 * Private structured memory summary, returned only to the authenticated owner.
 */
export type AiUiBlockPayloadMemory = {
  view: AiUiBlockPayloadMemoryView;
  /** @maxItems 6 */
  groups: AiUiBlockPayloadMemoryGroupsItem[];
};

/**
 * G2 conversational answer: its class (CONVERSATIONAL_RESPONSE, GROUNDED_ADVICE, CLARIFICATION_REQUIRED), the data scope it is grounded in (DINAR_INTERNAL or GENERAL_KNOWLEDGE), deterministic statistics and reasons, and an optional topic (SPONSORED_PLACEMENT, MARKETING_CLAIMS_BLOCKED with the refused claim kinds, MARKETING_COPY for copy grounded in the seller's own listing record). Never an action.
 */
export type AiUiBlockPayloadAdvice = { [key: string]: unknown };

/**
 * Allowlisted price-negotiation view for one of its two parties (review, status or list), rebuilt from the negotiation authority on every read.
 */
export type AiUiBlockPayloadNegotiation = { [key: string]: unknown };

/**
 * DINAR NEXT G2 buyer–seller inquiry view for one of its two parties (draft review, status, incoming message, list, notice), rebuilt from the inquiry authority on every read. Messages carry their author role and provenance (BUYER_AUTHORED, SELLER_AUTHORED, DINAR_DRAFT_APPROVED) and per-message submitted/delivered/read times. A verified seller may receive a staging-only email alert for a new inquiry; the alert omits buyer contact details and message content. Delivery status is shown separately from the in-app conversation. Never contains phone numbers, addresses or the other party's account id.
 */
export type AiUiBlockPayloadInquiry = { [key: string]: unknown };

/**
 * Universal product control view (APP_THEME, MARKET_SWITCH_REVIEW/STATUS, PROFILE_REVIEW/STATUS, CONTROL_NOTICE, PRIVACY_EXPORT), validated by ProductControlPayload in @workspace/api-zod/conversation-runtime. Theme changes are client actions whose status (REQUESTED, APPLIED, FAILED) is the device's own acknowledgement; market and profile reviews show their pending action's real status. Never contains secrets, coordinates or another user's data.
 */
export type AiUiBlockPayloadControl = { [key: string]: unknown };

/**
 * Monetization V3 commercial view (commercial balance, top-up and purchase reviews, campaigns and aggregate results, Market Pulse, DINAR Business), and the G1 AI usage card (AI_USAGE: plan tier, per-resource requests and tokens consumed in the current period, renewal boundary) and plan comparison (AI_PLANS: allowances per tier, configured prices or "not configured", billing connection state), rebuilt from server state on every read. Never contains buyer identity, ledger keys, provider costs or secrets.
 */
export type AiUiBlockPayloadCommerce = { [key: string]: unknown };

